const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const layout = (title, intro, rows, note, badgeColor, badge) => `<!DOCTYPE html><html><body style="margin:0;background:#F8F5EF;font-family:Arial,Helvetica,sans-serif;color:#3A332E">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#F8F5EF;padding:28px 12px"><tr><td align="center">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border:1px solid #E3DACF;border-radius:16px;overflow:hidden">
<tr><td style="background:#BD7E83;padding:26px 30px;color:#ffffff"><div style="font-family:Georgia,serif;font-size:24px;font-weight:bold">Blush &amp; Bloom Salon</div><div style="font-size:11px;letter-spacing:3px;opacity:.9">YOUR MOMENT TO BLOOM</div></td></tr>
<tr><td style="padding:30px">
<span style="display:inline-block;padding:4px 12px;border-radius:999px;background:${badgeColor};color:#3A332E;font-size:12px;font-weight:bold">${badge}</span>
<h1 style="font-family:Georgia,serif;font-size:24px;margin:16px 0 8px">${title}</h1>
<p style="font-size:15px;line-height:1.6;color:#6E645C;margin:0 0 20px">${intro}</p>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#F8F5EF;border-radius:12px;padding:6px 16px">${rows}</table>
<p style="font-size:13px;line-height:1.6;color:#6E645C;margin:20px 0 0">${note}</p>
</td></tr>
<tr><td style="padding:18px 30px;border-top:1px solid #E3DACF;font-size:12px;color:#89978B">Blush &amp; Bloom Salon · This is an automated message about your appointment. Please do not reply directly to this email; use the Contact page on our website.</td></tr>
</table></td></tr></table></body></html>`;
const row = (label, value) => `<tr><td style="padding:10px 0;font-size:12px;letter-spacing:1px;color:#89978B;text-transform:uppercase;width:40%">${label}</td><td style="padding:10px 0;font-size:15px;font-weight:bold">${esc(value)}</td></tr>`;

// Build the right email for the appointment event sent by Laravel.
const p = $input.first().json.body ?? {};
const a = p.appointment ?? {};
if (!p.event_id || !a.reference || !a.customer_email) throw new Error('Invalid appointment event payload');

const rows = row('Reference', a.reference) + row('Service', a.service) + row('Date', a.date_label) + row('Time', a.time_label) + (a.price ? row('Starting price', a.price) : '');
let email = null;

if (p.event === 'appointment.created') {
  email = { subject: `We received your booking request – ${a.reference}`,
    html: layout(`Thank you, ${esc(a.customer_name)}!`, 'We have received your appointment request. <strong>Your booking is PENDING and is not yet confirmed.</strong> Our team will review it and email you once it is confirmed.', rows,
      'Keep your booking reference. You can use it with your email to check your status through our website assistant.', '#F4EBDA', 'PENDING') };
} else if (p.event === 'appointment.status_changed' && a.status === 'Confirmed') {
  email = { subject: `Your appointment is confirmed – ${a.reference}`,
    html: layout(`See you soon, ${esc(a.customer_name)}!`, 'Good news — your appointment at Blush &amp; Bloom Salon is <strong>CONFIRMED</strong>.', rows,
      'Please arrive a few minutes early. If you need to change your appointment, contact us through our website.', '#E3ECE4', 'CONFIRMED') };
} else if (p.event === 'appointment.status_changed' && (a.status === 'Cancelled' || a.status === 'Rejected')) {
  const word = a.status === 'Rejected' ? 'could not be accepted' : 'has been cancelled';
  email = { subject: `Update on your appointment – ${a.reference}`,
    html: layout(`Hello ${esc(a.customer_name)},`, `We are sorry — your appointment request <strong>${word}</strong>.`, rows,
      'You are welcome to book another time on our website, or contact us if you have any questions.', '#F5E3E4', a.status.toUpperCase()) };
}

// Other events (e.g. Completed, Pending again, rescheduled) do not send an email in this workflow.
return [{ json: { send: !!email, event_id: p.event_id, to: a.customer_email, subject: email?.subject ?? '', html: email?.html ?? '' } }];
